    static Sprite Import(string path){AssetDatabase.ImportAsset(path);var i=(TextureImporter)AssetImporter.GetAtPath(path);i.textureType=TextureImporterType.Sprite;i.spriteImportMode=SpriteImportMode.Single;i.spritePixelsPerUnit=32;i.filterMode=FilterMode.Point;i.mipmapEnabled=false;i.textureCompression=TextureImporterCompression.Uncompressed;i.alphaIsTransparency=true;i.maxTextureSize=2048;i.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Sprite>(path);}
    static Sprite Reduce(string source,string dest,int w,int h,bool alpha){var bytes=File.ReadAllBytes(source);var raw=new Texture2D(2,2);raw.LoadImage(bytes);var t=new Texture2D(w,h,TextureFormat.RGBA32,false);for(int y=0;y<h;y++)for(int x=0;x<w;x++){var c=raw.GetPixel(Mathf.Min(raw.width-1,(int)((x+.5f)*raw.width/w)),Mathf.Min(raw.height-1,(int)((y+.5f)*raw.height/h)));if(alpha&&c.a<.5f)c=Color.clear;t.SetPixel(x,y,c);}t.Apply();File.WriteAllBytes(dest,t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(raw);return Import(dest);}
