        var hud=Obj("FastingTopDownHUD");var canvas=hud.AddComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;var scaler=hud.AddComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(960,540);scaler.matchWidthOrHeight=.5f;hud.AddComponent<GraphicRaycaster>();
        game.visionPanels=new UnityEngine.UI.Image[4];for(int n=0;n<4;n++)game.visionPanels[n]=Image("PartialVision_"+n,hud.transform,Vector2.zero,Vector2.zero,Vector2.zero,Color.clear);
