        game.hearts=new UnityEngine.UI.Image[5];for(int n=0;n<5;n++){game.hearts[n]=Image("Health"+n,hud.transform,new Vector2(0,1),new Vector2(780+n*30,-48),new Vector2(23,12),new Color(1,.5f,.3f));game.hearts[n].type=UnityEngine.UI.Image.Type.Filled;game.hearts[n].fillMethod=UnityEngine.UI.Image.FillMethod.Horizontal;}
